 public sealed class EquipmentCrudObserver:LabPlugin {
  public EquipmentCrudObserver(string u,string s):base(u,s){}
  public override void Execute(IServiceProvider p){
   var c=Context(p);if(c.PrimaryEntityName!="pqvd_equipment"||c.Depth!=1||!new[]{"Create","Update","Delete"}.Contains(c.MessageName)||!(c is IPluginExecutionContext2 portal))return;
   Guid actor;try{if(!portal.IsPortalsClientCall||(actor=portal.PortalsContactId)==Guid.Empty)return;}catch{return;}
   var target=c.InputParameters.Contains("Target")?c.InputParameters["Target"]:null;var entity=target as Entity;var targetId=entity?.Id??(target as EntityReference)?.Id??Guid.Empty;
   if(targetId==Guid.Empty&&entity!=null)targetId=entity.GetAttributeValue<Guid>("pqvd_equipmentid");if(targetId==Guid.Empty||c.PrimaryEntityId!=Guid.Empty&&c.PrimaryEntityId!=targetId)return;
   if(!Guid.TryParse(Configuration.writerId,out var writer)||!Configuration.Trusted(writer))return;var svc=Service(p,writer);
   Entity equipment;if(c.MessageName=="Create")equipment=entity;else {equipment=c.Stage==10?svc.Retrieve("pqvd_equipment",targetId,new ColumnSet("pqvd_name","pqvd_canaryrunid","pqvd_assettag","pqvd_equipmentstate","pqvd_currentassignmentid")):Before(c);if(equipment==null||equipment.Id!=targetId)return;}
   var marker=(c.MessageName=="Delete"?equipment:entity)?.GetAttributeValue<string>("pqvd_name");if(marker?.StartsWith("CO-OP:",StringComparison.Ordinal)!=true||!Guid.TryParse(marker.Substring(6),out var operation)||marker!="CO-OP:"+operation.ToString("D").ToLowerInvariant())return;
   var append=Configuration.allowOwnedEquipmentLookupTests&&c.MessageName=="Update"&&entity?.Contains("pqvd_roomid")==true;if(append&&(entity.GetAttributeValue<EntityReference>("pqvd_roomid")?.LogicalName!="pqvd_room"||Lookup(entity,"pqvd_roomid")==Guid.Empty))return;
   var caseId=append?"PORTAL-EQUIPMENT-APPEND":"PORTAL-EQUIPMENT-CRUD";var variant="TARGET:"+targetId.ToString("D").ToLowerInvariant()+(append?";ROOM:"+Lookup(entity,"pqvd_roomid").ToString("D"):"");
   var runId=Lookup(equipment,"pqvd_canaryrunid");if(runId==Guid.Empty||equipment.GetAttributeValue<string>("pqvd_assettag")?.StartsWith("CO-CANARY-",StringComparison.Ordinal)!=true||Lookup(equipment,"pqvd_currentassignmentid")!=Guid.Empty||equipment.GetAttributeValue<OptionSetValue>("pqvd_equipmentstate")?.Value!=183270000)return;
   var intents=new QueryExpression("pqvd_testoperation"){TopCount=2,ColumnSet=new ColumnSet("pqvd_runid","pqvd_runnercontactid","pqvd_expectedmessage","pqvd_roottable","pqvd_lane","pqvd_actorprovenance","pqvd_caseid","pqvd_variant","pqvd_markertime","pqvd_markeroperation","createdby")};
   intents.Criteria.AddCondition("pqvd_testoperationid",ConditionOperator.Equal,operation);
   foreach(var pair in new[]{new KeyValuePair<string,object>("pqvd_caseid",caseId),new KeyValuePair<string,object>("pqvd_variant",variant),new KeyValuePair<string,object>("pqvd_expectedmessage",c.MessageName),new KeyValuePair<string,object>("pqvd_roottable","pqvd_equipment"),new KeyValuePair<string,object>("pqvd_runid",runId),new KeyValuePair<string,object>("pqvd_runnercontactid",actor),new KeyValuePair<string,object>("pqvd_lane",183270001),new KeyValuePair<string,object>("pqvd_actorprovenance","SDKConfiguredIdentity.RelationshipClaim")})intents.Criteria.AddCondition(pair.Key,ConditionOperator.Equal,pair.Value);
   var found=svc.RetrieveMultiple(intents).Entities;if(found.Count!=1)return;var intent=found[0];var created=Lookup(intent,"createdby");var when=intent.GetAttributeValue<DateTime>("pqvd_markertime");var age=c.OperationCreatedOn.ToUniversalTime()-when.ToUniversalTime();if(intent.Id!=operation||!Configuration.Trusted(created)||age<TimeSpan.Zero||age>TimeSpan.FromMinutes(30)||intent.GetAttributeValue<string>("pqvd_markeroperation")!=marker)return;
   if(intent.GetAttributeValue<string>("pqvd_caseid")!=caseId||intent.GetAttributeValue<string>("pqvd_variant")!=variant||intent.GetAttributeValue<string>("pqvd_expectedmessage")!=c.MessageName||intent.GetAttributeValue<string>("pqvd_roottable")!="pqvd_equipment"||intent.GetAttributeValue<string>("pqvd_actorprovenance")!="SDKConfiguredIdentity.RelationshipClaim"||intent.GetAttributeValue<OptionSetValue>("pqvd_lane")?.Value!=183270001||Lookup(intent,"pqvd_runid")!=runId||Lookup(intent,"pqvd_runnercontactid")!=actor)return;
   var run=svc.Retrieve("pqvd_testrun",runId,new ColumnSet("pqvd_runnercontactid","createdby"));if(Lookup(run,"pqvd_runnercontactid")!=actor||!Configuration.Trusted(Lookup(run,"createdby")))return;
   Recording.Capture(p,Configuration,intent.Id,"EquipmentCrud."+c.MessageName+".Stage"+c.Stage+".Order"+Configuration.order,new{actorBinding="RuntimePortalsContactMatched.ConfiguredSDKTargetIntent",targetId,runId,expectedMessage=c.MessageName,provenance=c.MessageName=="Create"?"ExplicitCreateTarget.OwnedStockCanary":c.Stage==10?"PreValidationSDKRead.OwnedStockCanary":"BeforeImage.OwnedStockCanary",boundEquipment=Snapshot.Value(equipment)});
  }
 }
 public sealed class PipelineContextObserver:LabPlugin {
  public PipelineContextObserver(string u,string s):base(u,s){}
  public override void Execute(IServiceProvider p){
   var c=Context(p);var targetReference=c.InputParameters.Contains("Target")?c.InputParameters["Target"] as EntityReference:null;var names=new[]{"pqvd_crudprobe","pqvd_chainnode"};var entity=names.Contains(c.PrimaryEntityName)?c.PrimaryEntityName:targetReference?.LogicalName;if(!names.Contains(entity))return;var op=Recording.Operation(c);
   if(entity=="pqvd_crudprobe"&&Configuration.allowOwnedEquipmentLookupTests&&Guid.TryParse(Configuration.writerId,out var writer)&&Configuration.Trusted(writer)){
    var target=Target(c);var service=Service(p,writer);var probe=Before(c);
    if(target?.Contains("pqvd_equipmentid")==true&&c.MessageName=="Update"){
     if(!Configuration.allowOwnedEquipmentLookupTests||!OwnedLookupTest.Actor(c,out _))return;
     if(c.Stage==10)probe=service.Retrieve("pqvd_crudprobe",target.Id,new ColumnSet("pqvd_ownercontactid","pqvd_runid","pqvd_activeoperationid","pqvd_equipmentid"));
     if(probe==null||probe.Id!=target.Id||target.GetAttributeValue<EntityReference>("pqvd_equipmentid")?.LogicalName!="pqvd_equipment")return;
     op=Lookup(probe,"pqvd_activeoperationid");var run=Lookup(probe,"pqvd_runid");var desired=Lookup(target,"pqvd_equipmentid");if(desired==Guid.Empty)return;
     if(OwnedLookupTest.Intent(service,Configuration,c,op,run,target.Id,"pqvd_crudprobe","PORTAL-EQUIPMENT-APPENDTO","TARGET:"+target.Id.ToString("D")+";EQUIPMENT:"+desired.ToString("D"))==null)return;
     var equipment=service.Retrieve("pqvd_equipment",desired,new ColumnSet("pqvd_canaryrunid","pqvd_assettag","pqvd_currentassignmentid","pqvd_equipmentstate"));if(equipment.Id!=desired||!OwnedLookupTest.Stock(equipment,run))return;
    }else if(op!=Guid.Empty){
     var intent=service.Retrieve("pqvd_testoperation",op,new ColumnSet("pqvd_caseid"));
     // SDK preparation stamps ActiveOperation before source freeze. That setup
     // is not a portal AppendTo call and must not enter its measured artifact set.
     if(intent.GetAttributeValue<string>("pqvd_caseid")=="PORTAL-EQUIPMENT-APPENDTO")return;
    }
   }
   if(op==Guid.Empty&&c.Depth>1&&targetReference?.LogicalName=="pqvd_chainnode"&&Configuration.Trusted(c.InitiatingUserId)){var query=new QueryExpression("pqvd_chainnode"){TopCount=1,ColumnSet=new ColumnSet("pqvd_operationid")};query.Criteria.AddCondition("pqvd_chainnodeid",ConditionOperator.Equal,targetReference.Id);var row=Service(p,c.UserId).RetrieveMultiple(query).Entities.FirstOrDefault();op=Lookup(row,"pqvd_operationid");}
   if(op==Guid.Empty)return;if(c.Stage==10&&!c.SharedVariables.Contains("pqvd.lab.prevalidation"))c.SharedVariables["pqvd.lab.prevalidation"]="observed";Recording.Capture(p,Configuration,op,"PipelineContext.Stage"+c.Stage+".Order"+Configuration.order,new{secureConfiguration=new{present=SecurePresent,valid=SecureValid,version=SecureVersion},unsecureVersion=Configuration.configVersion});
  }
 }
 public sealed class ChainA:LabPlugin {
  public ChainA(string u,string s):base(u,s){}
  public override void Execute(IServiceProvider p){var c=Context(p);var t=Target(c);if(t==null||!t.Contains("pqvd_triggernonce"))return;var row=c.PostEntityImages.Contains("After")?c.PostEntityImages["After"]:null;Require(row!=null,"ChainA requires After image.");if(row.GetAttributeValue<string>("pqvd_triggernonce")==Before(c)?.GetAttributeValue<string>("pqvd_triggernonce"))return;var op=Lookup(row,"pqvd_activeoperationid");Require(op!=Guid.Empty,"ChainA operation missing.");var svc=Service(p,c.UserId);var operation=svc.Retrieve("pqvd_testoperation",op,new ColumnSet("pqvd_markerutc"));Recording.Capture(p,Configuration,op,"ChainA",new{scenario=row.GetAttributeValue<string>("pqvd_pluginscenario"),budget=row.GetAttributeValue<int>("pqvd_hopbudget")});
   var e=new Entity("pqvd_chainnode");e["pqvd_name"]="Chain B "+op;e["pqvd_operationid"]=new EntityReference("pqvd_testoperation",op);e["pqvd_nodecode"]="B-"+row.GetAttributeValue<string>("pqvd_triggernonce");e["pqvd_hop"]="B";e["pqvd_hopindex"]=1;e["pqvd_scenario"]=row.GetAttributeValue<string>("pqvd_pluginscenario");e["pqvd_requestnonce"]=row.GetAttributeValue<string>("pqvd_triggernonce");e["pqvd_querymarkerutc"]=operation.GetAttributeValue<string>("pqvd_markerutc");e["pqvd_payloadjson"]=Snapshot.Json(new{budget=row.GetAttributeValue<int>("pqvd_hopbudget"),startedAt=DateTime.UtcNow.ToString("o")});var request=new CreateRequest{Target=e};request["tag"]="CO-OP:"+op+";ChainA";svc.Execute(request);
  }
 }
 public sealed class ChainB:LabPlugin {
  public ChainB(string u,string s):base(u,s){}
  public override void Execute(IServiceProvider p){var c=Context(p);var t=Target(c);if(t?.GetAttributeValue<string>("pqvd_hop")!="B")return;var op=Lookup(t,"pqvd_operationid");Recording.Capture(p,Configuration,op,"ChainB",new{transition="B->C"});var e=new Entity("pqvd_chainnode",c.PrimaryEntityId);e["pqvd_hop"]="C";e["pqvd_configstatus"]="ChainStep:"+c.OwningExtension.Id;e["pqvd_requestnonce"]=Guid.NewGuid().ToString();e["pqvd_sampletext"]="Typed sample";e["pqvd_sampledecimal"]=123.4567m;e["pqvd_samplemoney"]=new Money(25.10m);e["pqvd_sampledate"]=new DateTime(2026,10,13);e["pqvd_sampletime"]=DateTime.UtcNow;e["pqvd_sampleboolean"]=true;e["pqvd_samplechoice"]=new OptionSetValue(183270000);e["pqvd_samplemultichoice"]=new OptionSetValueCollection{new OptionSetValue(183270000),new OptionSetValue(183270002)};var req=new UpdateRequest{Target=e};Service(p,c.UserId).Execute(req);}
 }
 public sealed class ChainC:LabPlugin {
  public ChainC(string u,string s):base(u,s){}
  static Entity Leaf(Entity parent,string code){var e=new Entity("pqvd_chainnode");e["pqvd_name"]="Leaf "+code;e["pqvd_operationid"]=parent["pqvd_operationid"];e["pqvd_nodecode"]=code;e["pqvd_parentnodeid"]=parent.ToEntityReference();e["pqvd_hop"]="Leaf";e["pqvd_hopindex"]=parent.GetAttributeValue<int>("pqvd_hopindex")+1;e["pqvd_scenario"]=parent["pqvd_scenario"];e["pqvd_querymarkerutc"]=parent["pqvd_querymarkerutc"];e["pqvd_configstatus"]=parent.GetAttributeValue<string>("pqvd_configstatus");return e;}
  static void Execute(IOrganizationService svc,OrganizationRequest request,Guid op){svc.Execute(request);}
  public override void Execute(IServiceProvider p){var c=Context(p);var before=Before(c);var after=c.PostEntityImages.Contains("After")?c.PostEntityImages["After"]:null;if(before?.GetAttributeValue<string>("pqvd_hop")!="B"||after?.GetAttributeValue<string>("pqvd_hop")!="C")return;var op=Lookup(after,"pqvd_operationid");var scenario=after.GetAttributeValue<string>("pqvd_scenario");c.SharedVariables["pqvd.lab.authorizedChainStepId"]=c.OwningExtension.Id.ToString();Recording.Capture(p,Configuration,op,"ChainC",new{scenario,transition="B->C",depth=c.Depth});var svc=Service(p,c.UserId);
   if(scenario=="ABC"||scenario=="P10"||scenario=="P11")return;
   if(scenario=="P02"){var leaf=Leaf(after,"P02-"+Guid.NewGuid().ToString("N"));var created=(CreateResponse)svc.Execute(new CreateRequest{Target=leaf});var update=new Entity("pqvd_chainnode",created.id);update["pqvd_sampletext"]="leaf updated";Execute(svc,new UpdateRequest{Target=update},op);Execute(svc,new RetrieveRequest{Target=new EntityReference("pqvd_chainnode",created.id),ColumnSet=new ColumnSet("pqvd_name","pqvd_sampletext")},op);var q=new QueryExpression("pqvd_chainnode"){ColumnSet=new ColumnSet("pqvd_name"),Criteria=new FilterExpression()};q.Criteria.AddCondition("pqvd_operationid",ConditionOperator.Equal,op);var marker=new FilterExpression(LogicalOperator.Or);marker.AddCondition("pqvd_name",ConditionOperator.Null);var and=new FilterExpression(LogicalOperator.And);and.AddCondition("pqvd_name",ConditionOperator.NotEqual,"CO-OP:"+op);and.AddCondition("pqvd_name",ConditionOperator.NotEqual,after.GetAttributeValue<string>("pqvd_querymarkerutc"));marker.AddFilter(and);q.Criteria.AddFilter(marker);Execute(svc,new RetrieveMultipleRequest{Query=q},op);var qa=new QueryByAttribute("pqvd_chainnode"){ColumnSet=new ColumnSet("pqvd_name")};qa.AddAttributeValue("pqvd_operationid",op);qa.AddAttributeValue("pqvd_querymarkerutc",after.GetAttributeValue<string>("pqvd_querymarkerutc"));Execute(svc,new RetrieveMultipleRequest{Query=qa},op);Execute(svc,new DeleteRequest{Target=new EntityReference("pqvd_chainnode",created.id)},op);return;}
   if(scenario=="P03"){var a=Leaf(after,"PEER-A-"+Guid.NewGuid().ToString("N"));var b=Leaf(after,"PEER-B-"+Guid.NewGuid().ToString("N"));a.Id=svc.Create(a);b.Id=svc.Create(b);var relationship=new Relationship("pqvd_chainnode_peers"){PrimaryEntityRole=EntityRole.Referencing};Execute(svc,new AssociateRequest{Target=a.ToEntityReference(),Relationship=relationship,RelatedEntities=new EntityReferenceCollection{b.ToEntityReference()}},op);Execute(svc,new DisassociateRequest{Target=a.ToEntityReference(),Relationship=relationship,RelatedEntities=new EntityReferenceCollection{b.ToEntityReference()}},op);return;}
   if(scenario=="P04"){var code="UPSERT-"+Guid.NewGuid().ToString("N");var leaf=Leaf(after,code);leaf.KeyAttributes["pqvd_operationid"]=after["pqvd_operationid"];leaf.KeyAttributes["pqvd_nodecode"]=code;leaf.Attributes.Remove("pqvd_operationid");leaf.Attributes.Remove("pqvd_nodecode");var first=(UpsertResponse)svc.Execute(new UpsertRequest{Target=leaf});var second=new Entity("pqvd_chainnode");second.KeyAttributes["pqvd_operationid"]=after["pqvd_operationid"];second.KeyAttributes["pqvd_nodecode"]=code;second["pqvd_sampletext"]="second upsert";var result=(UpsertResponse)svc.Execute(new UpsertRequest{Target=second});Recording.Capture(p,Configuration,op,"UpsertResults",new{first.RecordCreated,id=first.Target.Id,secondRecordCreated=result.RecordCreated,secondId=result.Target.Id});return;}
   if(scenario=="P05"){Require(Guid.TryParse(Configuration.teamId,out var team),"Assign demo team is not configured.");Execute(svc,new AssignRequest{Target=after.ToEntityReference(),Assignee=new EntityReference("team",team)},op);return;}
   if(scenario=="P06"){var update=new Entity("pqvd_chainnode",after.Id);update["statecode"]=new OptionSetValue(1);update["statuscode"]=new OptionSetValue(2);Execute(svc,new UpdateRequest{Target=update},op);Execute(svc,new SetStateRequest{EntityMoniker=after.ToEntityReference(),State=new OptionSetValue(0),Status=new OptionSetValue(1)},op);return;}
   if(scenario=="P07"){var req=new OrganizationRequest("pqvd_EchoLabContext");req["OperationId"]=op;req["Payload"]="Synthetic typed echo";var response=svc.Execute(req);Recording.Capture(p,Configuration,op,"CustomApiResponse",response.Results.ToDictionary(a=>a.Key,a=>Snapshot.Value(a.Value)));return;}
   if(scenario=="P08"){Require(Configuration.captureMode=="DurableCollector","rollback requires durable collector.");throw new InvalidPluginExecutionException("CO controlled rollback P08.");}
   if(scenario=="P09"){var settings=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<System.Collections.Generic.Dictionary<string,object>>(after.GetAttributeValue<string>("pqvd_payloadjson"));var budget=Convert.ToInt32(settings["budget"]);Require(budget>=1&&budget<=10,"depth budget invalid.");var leaf=Leaf(after,"DEPTH-"+Guid.NewGuid().ToString("N"));leaf["pqvd_hop"]="Depth";leaf["pqvd_scenario"]="Depth";leaf["pqvd_hopindex"]=1;leaf["pqvd_payloadjson"]=Snapshot.Json(new{budget,startedAt=settings["startedAt"]});Execute(svc,new CreateRequest{Target=leaf},op);return;}
   if(scenario=="P12"){var environment=new OrganizationRequest("RetrieveEnvironmentVariableValue");environment["DefinitionSchemaName"]="pqvd_LabProfile";var result=svc.Execute(environment);Recording.Capture(p,Configuration,op,"ConfigurationResult",new{securePresent=SecurePresent,secureValid=SecureValid,secureVersion=SecureVersion,ordinaryValue=result.Results.Contains("Value")?Snapshot.Value(result.Results["Value"]):null});return;}
   throw new InvalidPluginExecutionException("CO cloud profile not configured or qualified.");
  }
 }
 public sealed class DepthChain:LabPlugin {
  public DepthChain(string u,string s):base(u,s){}
  public override void Execute(IServiceProvider p){var c=Context(p);var t=Target(c);if(t?.GetAttributeValue<string>("pqvd_hop")!="Depth"||t.GetAttributeValue<string>("pqvd_scenario")!="Depth")return;var values=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<System.Collections.Generic.Dictionary<string,object>>(t.GetAttributeValue<string>("pqvd_payloadjson"));var budget=Convert.ToInt32(values["budget"]);var hop=t.GetAttributeValue<int>("pqvd_hopindex");Require(budget>=1&&budget<=10&&hop>=1&&hop<=budget,"depth hop/budget invalid.");var started=DateTime.Parse(Convert.ToString(values["startedAt"]),System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.RoundtripKind);Require(DateTime.UtcNow-started<TimeSpan.FromSeconds(60),"suite wall-clock budget exceeded.");var op=Lookup(t,"pqvd_operationid");Recording.Capture(p,Configuration,op,"DepthChain",new{hop,budget,observedDepth=c.Depth});if(hop>=budget)return;var e=new Entity("pqvd_chainnode");e["pqvd_name"]="Depth "+(hop+1);e["pqvd_operationid"]=t["pqvd_operationid"];e["pqvd_nodecode"]="DEPTH-"+Guid.NewGuid().ToString("N");e["pqvd_parentnodeid"]=new EntityReference("pqvd_chainnode",c.PrimaryEntityId);e["pqvd_hop"]="Depth";e["pqvd_hopindex"]=hop+1;e["pqvd_scenario"]="Depth";e["pqvd_querymarkerutc"]=t["pqvd_querymarkerutc"];e["pqvd_payloadjson"]=t["pqvd_payloadjson"];var req=new CreateRequest{Target=e};Service(p,c.UserId).Execute(req);}
 }
 public sealed class AsyncContextObserver:LabPlugin {
  public AsyncContextObserver(string u,string s):base(u,s){}
  public override void Execute(IServiceProvider p){var c=Context(p);var row=c.PostEntityImages.Contains("After")?c.PostEntityImages["After"]:null;if(row?.GetAttributeValue<string>("pqvd_pluginscenario")!="P10")return;Recording.Capture(p,Configuration,Lookup(row,"pqvd_activeoperationid"),"AsyncContext",new{separateExecution=true,persistedNonce=row.GetAttributeValue<string>("pqvd_triggernonce")});}
 }
 public sealed class EchoLabContext:IPlugin {
  public void Execute(IServiceProvider p){var c=(IPluginExecutionContext)p.GetService(typeof(IPluginExecutionContext));if(!(c.InputParameters["OperationId"] is Guid op))throw new InvalidPluginExecutionException("CO OperationId required.");var payload=c.InputParameters.Contains("Payload")?c.InputParameters["Payload"] as string:null;if(payload?.Length>4096)throw new InvalidPluginExecutionException("CO echo payload too large.");var svc=((IOrganizationServiceFactory)p.GetService(typeof(IOrganizationServiceFactory))).CreateOrganizationService(c.UserId);svc.Retrieve("pqvd_testoperation",op,new ColumnSet("pqvd_runid"));var span=Guid.NewGuid();c.OutputParameters["SummaryJson"]=Snapshot.Json(new{schemaVersion=1,operationId=op,spanId=span,message=c.MessageName,depth=c.Depth,stage=c.Stage,userId=c.UserId,initiatingUserId=c.InitiatingUserId,payload});c.OutputParameters["SpanId"]=span;}
 }
